INSERT INTO kingdom_verses (verse_id, strand, strand_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = '1-chronicles' AND c.chapter_number = 5 AND v.verse_number = 1), 'kingdom', 'The kingdom', 'The ruler from Yahudah (Judah), the birthright with Joseph — neither holds it all', $card$*Now the sons of Reuben the firstborn of Yashar'el (Israel), (for he was the firstborn; but, forasmuch as he defiled his father’s bed, his birthright was given unto the sons of Joseph the son of Yashar'el (Israel): and the genealogy is not to be reckoned after the birthright.* (1 Chronicles 5:1)

