DO $verify$
DECLARE
    n INT;
BEGIN
    SELECT COUNT(*) INTO n FROM kingdom_verses;
    IF n < 487 THEN
        RAISE EXCEPTION 'session205 seed verify failed: % rows (expected >= 487)', n;
    END IF;
    RAISE NOTICE 'session205 seed verified: % kingdom verses live.', n;
END
$verify$;

COMMIT;
